anzahl = 0
for zahl in range(1, 31):
    if zahl % 7 == 0:
        anzahl += 1
print(f"{anzahl} Zahlen zwischen 1 und 30 sind durch 7 teilbar.")
# Ausgabe: 4 Zahlen zwischen 1 und 30 sind durch 7 teilbar.

anzahl = int(input("Wie viele Noten? "))
summe = 0
for i in range(anzahl):
    note = int(input(f"Note {i + 1}: "))
    summe += note

if anzahl > 0:
    print(f"Durchschnitt: {round(summe / anzahl, 2)}")
else:
    print("Keine Noten eingegeben.")
# Bei 1, 2, 2 → Durchschnitt: 1.67

zahl = 21
ist_primzahl = True

for teiler in range(2, zahl):
    if zahl % teiler == 0:
        ist_primzahl = False
        break  # ein Teiler reicht

if ist_primzahl:
    print(f"{zahl} ist eine Primzahl.")
else:
    print(f"{zahl} ist keine Primzahl.")
# Ausgabe: 21 ist keine Primzahl.

